package ama.transcript;
import java.util.*;import java.lang.reflect.*;import java.time.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class Task11HistoryCursorTest {
 static final String M="12345678-1234-4234-8234-123456789abc",P="12345678-1234-4234-8234-123456789abd",I="12345678-1234-4234-8234-123456789abe";
 Class<?> type(){return assertDoesNotThrow(()->Class.forName("ama.transcript.PublicationHistoryCursor"),"History requires route-bound typed keyset cursors");}
 Object call(String name,Class<?>[] types,Object...args)throws Exception{var m=type().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(null,args);}
 String encode(String route,Map<String,Object>row)throws Exception{return (String)call("encode",new Class[]{String.class,String.class,String.class,Map.class},route,M,P,row);}
 Object decode(String route,String meeting,String pub,String cursor)throws Exception{return call("decode",new Class[]{String.class,String.class,String.class,String.class},route,meeting,pub,cursor);}
 String wire(String text){return Base64.getUrlEncoder().withoutPadding().encodeToString(text.getBytes(StandardCharsets.US_ASCII));}
 @Test void finalCursorRejectsOtherMeetingAndOtherRoute()throws Exception{String c=encode("finals",Map.of("meeting_revision",13L));assertNotNull(decode("finals",M,P,c));assertThrows(InvocationTargetException.class,()->decode("finals",P,P,c));assertThrows(InvocationTargetException.class,()->decode("submissions",M,P,c));assertThrows(InvocationTargetException.class,()->decode("finals",M,P,"13"));}
 @Test void attemptsRequireCanonicalMicrosecondTimeAndBase64RoundTrip()throws Exception{var row=Map.<String,Object>of("created_at",LocalDateTime.of(2026,10,25,12,0),"id",I);String c=encode("attempts",row);assertNotNull(decode("attempts",M,P,c));assertThrows(InvocationTargetException.class,()->decode("attempts",M,P,wire("v1|attempts|"+M+"|"+P+"|2026-10-25T12:00:00|"+I)));assertThrows(InvocationTargetException.class,()->decode("attempts",M,P,c+"="));assertThrows(InvocationTargetException.class,()->decode("attempts",M,M,c));}
 @Test void equalTimeKeysUseExactCanonicalUuidAndNoStringTimeComparison()throws Exception{String c=encode("attempts",Map.of("created_at",java.sql.Timestamp.valueOf("2026-10-25 12:00:00"),"id",I));assertNotNull(decode("attempts",M,P,c));assertThrows(InvocationTargetException.class,()->decode("attempts",M,P,wire("v1|attempts|"+M+"|"+P+"|2026-10-25T12:00:00.000000|"+I.toUpperCase())));}
 @Test void actualAttemptPageBindsTypedTimeTwiceThenUuid()throws Exception {var method=assertDoesNotThrow(()->JdbcPublicationQueries.class.getDeclaredMethod("attemptPage",String.class,PublicationHistoryCursor.Key.class));method.setAccessible(true);var key=new PublicationHistoryCursor.Key(null,LocalDateTime.of(2026,10,25,12,0),I);Object page=method.invoke(null,P,key);var sql=page.getClass().getDeclaredMethod("sql");var args=page.getClass().getDeclaredMethod("args");sql.setAccessible(true);args.setAccessible(true);assertTrue(sql.invoke(page).toString().contains("(created_at<? OR (created_at=? AND id<?)) ORDER BY created_at DESC,id DESC"));assertEquals(List.of(P,key.created(),key.created(),I),args.invoke(page));}
 @Test void countersRespectLosslessBoundaryAndRejectOverflowOrZero()throws Exception{assertNotNull(decode("submissions",M,P,encode("submissions",Map.of("submission_no",9223372036854775806L))));for(String n:List.of("0","01","9223372036854775807","9223372036854775808"))assertThrows(InvocationTargetException.class,()->decode("submissions",M,P,wire("v1|submissions|"+M+"|"+P+"|"+n)));}
}
